def collaboration_watcher_health(app) -> dict:
    state = getattr(app, "collaboration_watcher_health", {})
    if not isinstance(state, dict):
        return {"status": "unknown"}
    return {
        key: state.get(key)
        for key in (
            "status",
            "consecutive_failures",
            "retry_in_seconds",
            "last_success_at",
            "last_error_at",
            "error_code",
        )
        if key in state
    }
